syntax:
C++ syntax for pointer to member functions:

class MyClass {
    public:
        virtual void virtualFunc();  // Virtual member function, resolved via vtable
        void nonVirtualFunc();      // Non-virtual, direct call after this-pointer adjustment
};

int main() {
    void (MyClass::*ptrToMember)() = &MyClass::virtualFunc;  // Pointer to member function
    MyClass obj;
    (obj.*ptrToMember)();  // Compiler synthesizes: adjust 'this' pointer and call via vtable if virtual
    // Implementation note: For virtual functions, the compiler generates assembly like:
    // mov rax, [obj]  ; Load vptr from object
    // call [rax + offset]  ; Index vtable and call
}

code_example:
#include <iostream>

class Base {
    public:
        virtual void virtualFunc() { std::cout << "Base virtual" << std::endl; }
        void nonVirtualFunc() { std::cout << "Base non-virtual" << std::endl; }
};

class Derived : public Base {
    public:
        void virtualFunc() override { std::cout << "Derived virtual" << std::endl; }  // Overrides base
};

int main() {
    void (Base::*ptrToVirtual)() = &Base::virtualFunc;  // Pointer to virtual member
    void (Base::*ptrToNonVirtual)() = &Base::nonVirtualFunc;  // Pointer to non-virtual member
    Derived derivedObj;
    (derivedObj.*ptrToVirtual)();  // Invokes Derived::virtualFunc via vtable
    (derivedObj.*ptrToNonVirtual)();  // Invokes Base::nonVirtualFunc directly
    return 0;
}
